const body = $input.first().json.body || {};
const storeId = String(body.storeId || '').trim();
const storeAlias = String(body.storeAlias || '').trim().toLowerCase();
const storeConfigVersion = Number(body.storeConfigVersion || 0);
const credentialVersionId = String(body.credentialVersionId || '').trim();
const requestRef = String(body.requestRef || '').trim();
const accountCurrency = String(body.accountCurrency || '').trim().toUpperCase();
const errors = {};
if (!/^[a-f0-9-]{36}$/i.test(storeId)) errors.storeId = 'storeId 必须是 UUID';
if (!/^[a-z0-9][a-z0-9-]{1,31}$/.test(storeAlias)) errors.storeAlias = 'storeAlias 格式无效';
if (!Number.isInteger(storeConfigVersion) || storeConfigVersion < 1) errors.storeConfigVersion = 'storeConfigVersion 必须是正整数';
if (!/^[a-f0-9-]{36}$/i.test(credentialVersionId)) errors.credentialVersionId = 'credentialVersionId 必须是 UUID';
if (!requestRef || requestRef.length > 180 || !/^[A-Za-z0-9._:|-]+$/.test(requestRef)) errors.requestRef = 'requestRef 格式无效';
if (accountCurrency !== 'CNY') errors.accountCurrency = 'WB 多店铺当前仅允许 CNY 账户币种';
if (Object.keys(errors).length) return [{ json: { valid: false, httpStatus: 400, ok: false, error: 'validation_error', message: '店铺预检参数无效', details: errors } }];
return [{ json: { valid: true, storeId, storeAlias, storeConfigVersion, credentialVersionId, requestRef, accountCurrency } }];

const input = $input.first().json || {};
const checks = [
  ['SELLER_INFO', {}],
  ['SELLER_WAREHOUSES', {}],
  ['PRICE_ACCESS_PROBE', {}],
  ['SUBJECTS_SEARCH', { locale: 'ru', limit: 1, offset: 0, name: '' }],
];
return checks.map(([operation, payload], index) => ({ json: {
  ...input, operation, payload, requestRef: input.requestRef + ':' + index + ':' + operation.toLowerCase(),
}, pairedItem: { item: 0 } }));

const request = $('Validate Store Preflight').first().json || {};
const responses = $input.all().map((item) => item.json || {});
const byOperation = Object.fromEntries(responses.map((entry) => [String(entry.operation || ''), entry]));
const summarize = (operation) => {
  const value = byOperation[operation] || {};
  return { ok: value.ok === true, statusCode: Number(value.statusCode || 0), deliveryState: String(value.deliveryState || ''),
    retryClass: String(value.retryClass || ''), error: value.error ? { code: String(value.error.code || ''), message: String(value.error.message || '').slice(0, 500) } : undefined };
};
const seller = byOperation.SELLER_INFO || {};
const warehouse = byOperation.SELLER_WAREHOUSES || {};
const prices = byOperation.PRICE_ACCESS_PROBE || {};
const content = byOperation.SUBJECTS_SEARCH || {};
const sellerBody = seller.body !== undefined ? seller.body : {};
const warehouseBody = warehouse.body !== undefined ? warehouse.body : {};
const priceBody = prices.body !== undefined ? prices.body : {};
const warehouses = Array.isArray(warehouseBody) ? warehouseBody : (warehouseBody.warehouses || warehouseBody.data || []);
const goods = priceBody?.data?.listGoods || priceBody?.data?.goods || priceBody?.data || [];
const firstGood = Array.isArray(goods) ? goods[0] : null;
const sellerId = String(sellerBody?.sid || sellerBody?.data?.sid || '').trim();
const sellerName = String(sellerBody?.name || sellerBody?.data?.name || '').trim();
const checks = {
  seller: summarize('SELLER_INFO'),
  content: summarize('SUBJECTS_SEARCH'),
  marketplace: summarize('SELLER_WAREHOUSES'),
  prices: summarize('PRICE_ACCESS_PROBE'),
};
const permissions = [];
if (checks.content.ok) permissions.push('content');
if (checks.prices.ok) permissions.push('prices');
if (checks.marketplace.ok) permissions.push('marketplace');
const normalizedWarehouses = Array.isArray(warehouses) ? warehouses
  .map((row) => ({ id: String(row?.id || row?.warehouseId || '').trim(), name: String(row?.name || '').trim() }))
  .filter((row) => row.id) : [];
const observedPriceCurrency = String(firstGood?.currencyIsoCode4217 || '').trim().toUpperCase();
const accountCurrency = observedPriceCurrency || String(request.accountCurrency || '').trim().toUpperCase();
const currencyVerified = Boolean(observedPriceCurrency);
const allChecksOk = Object.values(checks).every((entry) => entry.ok);
const ok = allChecksOk && Boolean(sellerId) && permissions.length === 3 && normalizedWarehouses.length > 0 && accountCurrency === 'CNY';
const failures = [
  ...Object.entries(checks).filter(([, value]) => !value.ok).map(([name]) => name + ' probe failed'),
  ...(!sellerId ? ['sellerId missing'] : []),
  ...(normalizedWarehouses.length ? [] : ['warehouse missing']),
  ...(accountCurrency === 'CNY' ? [] : ['account currency must be CNY']),
];
const report = {
  ok,
  ...(sellerId ? { sellerId } : {}),
  ...(sellerName ? { sellerName } : {}),
  permissions,
  ...(accountCurrency ? { accountCurrency } : {}),
  warehouses: normalizedWarehouses,
  ...(!ok ? { errorCode: 'WB_STORE_PREFLIGHT_FAILED', errorMessage: failures.join('; ').slice(0, 4000) || 'WB 店铺预检未通过' } : {}),
  checkedAt: new Date().toISOString(),
  details: {
    checks,
    observedPriceCurrency: observedPriceCurrency || null,
    currencySource: observedPriceCurrency ? 'WB_PRICE_LIST' : 'STORE_CONFIG',
    currencyVerified,
    currencyVerification: currencyVerified ? 'VERIFIED' : 'DEFERRED_EMPTY_CATALOG',
  },
};
return [{ json: { ...request, report } }];

async function runtimeRequest(method, endpoint, body, timeoutMs = 30_000) {
  const base = String($env.MERCHROUTE_RUNTIME_BASE_URL || 'http://127.0.0.1:4173').replace(/\/+$/, '');
  const key = String($env.MERCHROUTE_RUNTIME_KEY || '').trim();
  if (!key) throw new Error('MERCHROUTE_RUNTIME_KEY 未配置，无法访问 MerchRoute WB runtime API');
  const RuntimeURL = require('url').URL;
  const target = new RuntimeURL(base + endpoint);
  const payload = body === undefined ? '' : JSON.stringify(body);
  const transport = target.protocol === 'https:' ? require('https') : require('http');
  const response = await new Promise((resolve, reject) => {
    const request = transport.request(target, {
      method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-MerchRoute-Runtime-Key': key,
        ...(payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}),
      },
    }, (incoming) => {
      const chunks = [];
      let bytes = 0;
      incoming.on('data', (chunk) => {
        bytes += chunk.length;
        if (bytes > 20 * 1024 * 1024) {
          request.destroy(new Error('MerchRoute runtime API 响应超过 20 MiB 限制'));
          return;
        }
        chunks.push(chunk);
      });
      incoming.on('end', () => resolve({
        status: Number(incoming.statusCode || 0),
        text: Buffer.concat(chunks).toString('utf8'),
      }));
    });
    const boundedTimeoutMs = Math.max(1_000, Math.min(180_000, Number(timeoutMs) || 30_000));
    request.setTimeout(boundedTimeoutMs, () => request.destroy(new Error('MerchRoute runtime API 请求超时')));
    request.on('error', reject);
    if (payload) request.write(payload);
    request.end();
  });
  const text = response.text;
  let data = {};
  if (text) {
    try { data = JSON.parse(text); } catch (_) { data = { raw: text }; }
  }
  if (response.status < 200 || response.status >= 300) {
    const nestedError = data && typeof data.error === 'object' && data.error !== null ? data.error : {};
    const errorValue = typeof data.error === 'string' ? data.error : '';
    const error = new Error(String(data.message || nestedError.message || errorValue || data.code || nestedError.code || ('MerchRoute runtime API HTTP ' + response.status)));
    error.code = String(data.code || nestedError.code || errorValue || 'RUNTIME_API_FAILED');
    error.httpStatus = response.status;
    error.details = data;
    throw error;
  }
  return data;
}
function toItems(value) {
  const rows = Array.isArray(value) ? value : value == null ? [] : [value];
  return rows.map((row) => ({ json: row || {} }));
}
function migrated(name) {
  return [{ json: { ok: false, migrated: true, error: 'MIGRATED_TO_POSTGRESQL', code: 'MIGRATED_TO_POSTGRESQL', message: name + ' 已迁移到 MerchRoute PostgreSQL runtime API' } }];
}
function runtimeFailureDetails(error) {
  const queue = [error];
  const seen = new Set();
  const codes = [];
  const messages = [];
  const statuses = [];
  while (queue.length && seen.size < 16) {
    const current = queue.shift();
    if (!current || typeof current !== 'object' || seen.has(current)) continue;
    seen.add(current);
    for (const key of ['code','errno','errorCode']) if (current[key] != null) codes.push(String(current[key]).toUpperCase());
    for (const key of ['message','description']) if (current[key]) messages.push(String(current[key]));
    for (const key of ['httpStatus','statusCode','httpCode','status']) {
      if (current[key] == null) continue;
      const status = Number(current[key]);
      if (Number.isFinite(status)) statuses.push(status);
    }
    for (const key of ['cause','error','originalError']) {
      if (current[key] && typeof current[key] === 'object') queue.push(current[key]);
    }
  }
  return { codes, messages, statuses };
}
function isRuntimeNetworkFailure(error) {
  const details = runtimeFailureDetails(error);
  const retryableCodes = new Set([
    'ETIMEDOUT','ESOCKETTIMEDOUT','ECONNRESET','ECONNABORTED','ECONNREFUSED','ENOTFOUND','EAI_AGAIN','EPIPE',
    'UND_ERR_CONNECT_TIMEOUT','UND_ERR_HEADERS_TIMEOUT','UND_ERR_BODY_TIMEOUT','UND_ERR_SOCKET',
  ]);
  if (details.codes.some((code) => retryableCodes.has(code))) return true;
  if (details.statuses.some((status) => [408, 425, 429].includes(status) || status >= 500)) return true;
  const message = details.messages.join(' | ');
  return /\b(?:ETIMEDOUT|ESOCKETTIMEDOUT|ECONNRESET|ECONNABORTED|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EPIPE|UND_ERR_CONNECT_TIMEOUT|UND_ERR_HEADERS_TIMEOUT|UND_ERR_BODY_TIMEOUT|UND_ERR_SOCKET)\b|fetch failed|failed to fetch|timed?\s*out|请求超时|socket hang up|temporary tls eof|network socket disconnected/i.test(message);
}
function persistentNetworkDelaySeconds(attempt) {
  const schedule = [30, 60, 300, 900];
  return schedule[Math.min(Math.max(1, Number(attempt || 1)), schedule.length) - 1];
}

const value = $input.first().json || {};
return (async () => {
  const data = await runtimeRequest('POST', '/api/v1/wb/runtime/stores/' + encodeURIComponent(String(value.storeId)) + '/preflight-report', {
    report: value.report, storeConfigVersion: Number(value.storeConfigVersion), credentialVersionId: String(value.credentialVersionId),
  });
  return [{ json: { httpStatus: 200, ok: true, accepted: true, storeId: value.storeId, report: data.report || value.report } }];
})();

const value = $input.first().json || {};
const raw = value.error && typeof value.error === 'object' ? value.error : value;
const status = Number(raw.httpStatus || raw.statusCode || 0);
return [{ json: { httpStatus: status === 409 ? 409 : 502, ok: false, accepted: false,
  error: status === 409 ? 'store_config_changed' : 'preflight_failed',
  message: status === 409 ? '店铺配置已变化，请重新发起预检' : 'WB 店铺预检失败，请查看任务执行记录' } }];

