return (async () => {
  const values = {};
  values["config_id"] = "default";
  if ("wb_runtime_config" === 'wb_runtime_config') {
    if ("Load Preflight Config" === 'Load Dispatch Config') {
      const gate = $getWorkflowStaticData('global');
      gate.runtimeNetworkRecovery = gate.runtimeNetworkRecovery && typeof gate.runtimeNetworkRecovery === 'object'
        ? gate.runtimeNetworkRecovery : {};
      const recovery = gate.runtimeNetworkRecovery;
      if (recovery.active === true && Number.isFinite(Date.parse(String(recovery.nextAttemptAt || '')))
          && Date.parse(String(recovery.nextAttemptAt)) > Date.now()) {
        return [{ json: { __runtimeNetworkWait: true, networkRecovery: recovery } }];
      }
      try {
        const data = await runtimeRequest('GET', '/api/v1/wb/runtime/config', undefined);
        if (recovery.active === true) {
          gate.runtimeNetworkRecovery = {
            ...recovery, active: false, recoveredAt: new Date().toISOString(), nextAttemptAt: null,
          };
        }
        return toItems(data.config || data);
      } catch (error) {
        if (!isRuntimeNetworkFailure(error)) throw error;
        const attempt = recovery.active === true ? Number(recovery.attempt || 0) + 1 : 1;
        const delaySeconds = persistentNetworkDelaySeconds(attempt);
        gate.runtimeNetworkRecovery = {
          active: true, phase: 'WB_RUNTIME_CONFIG', resumeState: 'DISPATCH', attempt,
          pauseStartedAt: recovery.pauseStartedAt || new Date().toISOString(),
          lastFailureAt: new Date().toISOString(),
          nextAttemptAt: new Date(Date.now() + delaySeconds * 1000).toISOString(),
          lastErrorCode: String(error?.code || 'RUNTIME_NETWORK_ERROR'),
          lastErrorMessage: String(error?.message || 'MerchRoute runtime API 网络不可用').slice(0, 1000),
        };
        return [{ json: { __runtimeNetworkWait: true, networkRecovery: gate.runtimeNetworkRecovery } }];
      }
    }
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/config', undefined);
    return toItems(data.config || data);
  }
  if ("wb_runtime_config" === 'wb_publish_jobs') {
    if (values.task_id) {
      try {
        const data = await runtimeRequest('GET', '/api/v1/wb/runtime/jobs/' + encodeURIComponent(String(values.task_id)), undefined);
        return toItems(data.job || data);
      } catch (error) {
        if ("Load Preflight Config" === 'Lookup Job Status' && Number(error.httpStatus || 0) === 404) {
          return [{ json: { __runtimeJobNotFound: true, task_id_requested: String(values.task_id) } }];
        }
        throw error;
      }
    }
    const params = ['pageSize=100'];
    if (values.product_code) params.push('productCode=' + encodeURIComponent(String(values.product_code)));
    if (values.store_id) params.push('storeId=' + encodeURIComponent(String(values.store_id)));
    if ("Load Preflight Config".includes('Dispatch')) params.push('due=true');
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/jobs?' + params.join('&'), undefined);
    const rows = Array.isArray(data.items) ? data.items : [];
    if ("Load Preflight Config" === 'Get Product Jobs' && rows.length === 0) {
      return [{ json: { __emptyProductJobs: true } }];
    }
    return toItems(rows);
  }
  if ("wb_runtime_config" === 'wb_product_registry') {
    if (!values.product_code) return [];
    const params = ['productCode=' + encodeURIComponent(String(values.product_code))];
    if (values.store_id) params.push('storeId=' + encodeURIComponent(String(values.store_id)));
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/registry?' + params.join('&'), undefined);
    return toItems(data.items || []);
  }
  if ("wb_runtime_config" === 'wb_category_templates') {
    if (!values.category_key) return [];
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/categories/' + encodeURIComponent(String(values.category_key)), undefined);
    return toItems(data.category || data);
  }
  return migrated("Load Preflight Config");
})();

